import{_ as n,I as s,c as o,o as i,a3 as a,b as l,w as t,a as c,J as d,a4 as h}from"./chunks/framework.Cc9k46oU.js";const k=JSON.parse('{"title":"Disaster Recovery (DR) and High Availability Design","description":"High availability (HA) and disaster recovery (DR) guide to ensure data integrity and achieve system recovery within an RTO of 15 minutes in enterprise environments","frontmatter":{"title":"Disaster Recovery (DR) and High Availability Design","shortTitle":"Disaster Recovery & DR","category":"Infrastructure & Security","sort":5,"description":"High availability (HA) and disaster recovery (DR) guide to ensure data integrity and achieve system recovery within an RTO of 15 minutes in enterprise environments","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/infra/disaster-recovery"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/infra/disaster-recovery"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/infra/disaster-recovery"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/infra/disaster-recovery"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/infra/disaster-recovery"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Disaster Recovery (DR) and High Availability Design | Empasy Docs"}],["meta",{"property":"og:description","content":"High availability (HA) and disaster recovery (DR) guide to ensure data integrity and achieve system recovery within an RTO of 15 minutes in enterprise environments"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/infra/disaster-recovery"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Disaster Recovery (DR) and High Availability Design | Empasy Docs"}],["meta",{"name":"twitter:description","content":"High availability (HA) and disaster recovery (DR) guide to ensure data integrity and achieve system recovery within an RTO of 15 minutes in enterprise environments"}]]},"headers":[],"relativePath":"en/infra/disaster-recovery.md","filePath":"en/infra/disaster-recovery.md","lastUpdated":1795293539000}'),p={name:"en/infra/disaster-recovery.md"};function y(g,e,u,m,v,f){const r=s("Mermaid");return i(),o("div",null,[e[1]||(e[1]=a('<h1 id="disaster-recovery-dr-and-high-availability-design" tabindex="-1">Disaster Recovery (DR) and High Availability Design <a class="header-anchor" href="#disaster-recovery-dr-and-high-availability-design" aria-label="Permalink to “Disaster Recovery (DR) and High Availability Design”">​</a></h1><h2 id="_1-overview-and-recovery-target-objectives" tabindex="-1">1. Overview and Recovery Target Objectives <a class="header-anchor" href="#_1-overview-and-recovery-target-objectives" aria-label="Permalink to “1. Overview and Recovery Target Objectives”">​</a></h2><p>To reliably support financial, manufacturing, and public-sector services where data loss is critical, SyncSeries defines clear recovery target metrics (RPO, RTO) and operates multi-region, redundant infrastructure.</p><ul><li><strong>RPO (Recovery Point Objective)</strong>: <strong>0 minutes</strong> (under synchronous replication) / <strong>within 1 minute</strong> (under asynchronous cross-region replication).</li><li><strong>RTO (Recovery Time Objective)</strong>: <strong>Within 15 minutes</strong> (based on completing traffic cutover to the secondary center when the primary center fails).</li></ul>',4)),(i(),l(h,null,{default:t(()=>[d(r,{id:"mermaid-21",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20PrimaryDC%20%5B%22Primary%20Data%20Center%20(Active)%22%5D%0A%20%20%20%20%20%20%20%20K8s_P%5B%22Kubernetes%20Worker%20Nodes%22%5D%0A%20%20%20%20%20%20%20%20PG_P%5B(%22PostgreSQL%2018.6%20Primary%22)%5D%0A%20%20%20%20%20%20%20%20Redis_P%5B(%22Redis%20Primary%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SecondaryDC%20%5B%22Disaster%20Recovery%20Center%20(Standby)%22%5D%0A%20%20%20%20%20%20%20%20K8s_S%5B%22Kubernetes%20Standby%20Nodes%22%5D%0A%20%20%20%20%20%20%20%20PG_S%5B(%22PostgreSQL%2018.6%20Standby%22)%5D%0A%20%20%20%20%20%20%20%20Redis_S%5B(%22Redis%20Replica%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20GSLB%5B%22GSLB%20%2F%20DNS%20Traffic%20Router%22%5D%20--%3E%20PrimaryDC%0A%20%20%20%20GSLB%20-.-%3E%20%7CFailover%20within%2015%20min%20on%20outage%7C%20SecondaryDC%0A%20%20%20%20%0A%20%20%20%20PG_P%20--%3E%20%7CSynchronous%20WAL%20Streaming%20Replication%7C%20PG_S%0A%20%20%20%20Redis_P%20--%3E%20%7CAsynchronous%20Memory%20Replication%7C%20Redis_S%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<hr><h2 id="_2-data-layer-high-availability-and-replication-architecture" tabindex="-1">2. Data Layer High Availability and Replication Architecture <a class="header-anchor" href="#_2-data-layer-high-availability-and-replication-architecture" aria-label="Permalink to “2. Data Layer High Availability and Replication Architecture”">​</a></h2><h3 id="_1-postgresql-18-6-pgvector-wal-streaming-replication" tabindex="-1">1) PostgreSQL 18.6 (pgvector) WAL Streaming Replication <a class="header-anchor" href="#_1-postgresql-18-6-pgvector-wal-streaming-replication" aria-label="Permalink to “1) PostgreSQL 18.6 (pgvector) WAL Streaming Replication”">​</a></h3><ul><li>Physical Streaming Replication in PostgreSQL 18.6 is applied to maintain consistency across business tables and AI embedding vector data.</li><li>By setting <code>synchronous_commit = on</code>, the final client response is returned only after the transaction commit signal has been written to the standby node&#39;s WAL (Write-Ahead Log), preventing commit loss during failures.</li></ul><div class="language-ini"><button title="Copy code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># postgresql.conf (Primary)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">wal_level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = replica</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_wal_senders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 10</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">wal_keep_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 4096MB</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">synchronous_commit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = on</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">synchronous_standby_names</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;FIRST 1 (dr_standby_node)&#39;</span></span></code></pre></div><h3 id="_2-point-in-time-recovery-pitr-pipeline" tabindex="-1">2) Point-In-Time Recovery (PITR) Pipeline <a class="header-anchor" href="#_2-point-in-time-recovery-pitr-pipeline" aria-label="Permalink to “2) Point-In-Time Recovery (PITR) Pipeline”">​</a></h3><ul><li>Every day at 02:00, a full Base Backup is compressed, encrypted, and stored in MinIO object storage.</li><li>Continuously generated WAL archive files are synchronized to secondary storage every 60 seconds, providing a PITR environment capable of precisely restoring the database to a specific minute or second in the event of data corruption caused by operator error.</li></ul><hr><h2 id="_3-redis-distributed-lock-and-session-replication" tabindex="-1">3. Redis Distributed Lock and Session Replication <a class="header-anchor" href="#_3-redis-distributed-lock-and-session-replication" aria-label="Permalink to “3. Redis Distributed Lock and Session Replication”">​</a></h2><ul><li>Distributed locks (<code>Redlock</code>) that prevent concurrent task collisions between agents and active user sessions are configured on a 3-node automatic failover cluster powered by Redis Sentinel.</li><li>If a critical hardware failure occurs on the master node, Sentinel quorum consensus automatically promotes a standby node to the new master within 3 seconds.</li></ul><hr><h2 id="_4-step-by-step-failover-procedure-during-a-disaster" tabindex="-1">4. Step-by-Step Failover Procedure During a Disaster <a class="header-anchor" href="#_4-step-by-step-failover-procedure-during-a-disaster" aria-label="Permalink to “4. Step-by-Step Failover Procedure During a Disaster”">​</a></h2><p>In the event of physical flooding, power outage, or network disconnection at the primary data center, traffic is failed over to the standby center in accordance with the following Standard Operating Procedure (SOP):</p><ol><li><strong>Detection and Outage Declaration (0–3 minutes)</strong>: <ul><li>An infrastructure critical alert is triggered if three external health-check probes observe sustained 5xx errors or unresponsiveness from the primary center for more than 180 seconds.</li></ul></li><li><strong>Secondary Database Promotion (3–7 minutes)</strong>: <ul><li>Execute the promotion command on the PostgreSQL Standby node in the DR center to switch it to read/write mode:<div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pg_ctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> promote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/postgresql/data</span></span></code></pre></div></li></ul></li><li><strong>Kubernetes Pod Scale-Out and Startup (7–10 minutes)</strong>: <ul><li>Immediately scale out the domain agent Deployment replicas in the secondary cluster from their standby baseline (1 instance) to production capacity (minimum 3 or more instances).</li></ul></li><li><strong>GSLB Traffic Cutover (10–15 minutes)</strong>: <ul><li>Shift Global Server Load Balancer (GSLB) weights to 0% for the primary center and 100% for the secondary center, and wait for the DNS TTL (60 seconds) to expire.</li><li>Perform final verification of healthy inbound service traffic and proper validation of authorized token sessions.</li></ul></li></ol><hr><h2 id="_5-scheduled-drills-and-recovery-verification" tabindex="-1">5. Scheduled Drills and Recovery Verification <a class="header-anchor" href="#_5-scheduled-drills-and-recovery-verification" aria-label="Permalink to “5. Scheduled Drills and Recovery Verification”">​</a></h2><ul><li><strong>Drill Frequency</strong>: Conduct scheduled DR simulation drills once per quarter.</li><li><strong>Verification Items</strong>: <ul><li>Forcefully sever the primary center network interface and measure total time to complete traffic cutover.</li><li>Perform a full reconciliation after cutover to verify zero data loss (0 missing records) across agent execution history and RAG vector indexes.</li><li>Compile a drill execution report and retain it as enterprise compliance audit evidence.</li></ul></li></ul>`,17))])}const D=n(p,[["render",y]]);export{k as __pageData,D as default};
